const sqtData = {{node:search_node_bcw4wTuU.data.data}};

const itemIds = [];

const collectItemIds = (line) => {
  const material = line?.material_id;
  const materialId =
    material && typeof material === "object"
      ? material.id
      : material;

  if (
    materialId !== undefined &&
    materialId !== null &&
    materialId !== ""
  ) {
    itemIds.push(String(materialId));
  }

  if (Array.isArray(line?.children)) {
    line.children.forEach(collectItemIds);
  }
};

(sqtData || []).forEach((quotation) => {
  (quotation.table_sqt || []).forEach(collectItemIds);
});

return {
  item_ids: [...new Set(itemIds)],
};

// ==========================================================================
// Map Data — Quotation → Sales Order
// --------------------------------------------------------------------------
// "single"   merges every selected quotation into ONE order. Nothing is written
//            here -- the record goes back to the page, which opens it in the
//            add form for review, so so_no is left blank for the form to fill.
// "multiple" produces one order per quotation for the Add Data node to insert,
//            stamped with the draft serial rule.
//
// Relation columns come back from a Get-many node as objects, not ids, so every
// id-typed field is unwrapped before it reaches the order -- an object landing
// on an id column comes back as a BigInt conversion failure.
// ==========================================================================
const referenceId = (value) => {
  if (value && typeof value === "object") return value.id || null;
  return value || null;
};

// 8dp is the maximum configurable column precision: rounding COMPUTED values there keeps
// every client-configured scale intact while killing float residue.
const q8 = (v) => Number((parseFloat(v) || 0).toFixed(8));

// ==========================================================================
// ITEM BUNDLES
// --------------------------------------------------------------------------
// An item bundle is ONE line on the quotation with the bundle's items beneath
// it, and it is ordered as a whole. The quotation hands that tree over in one
// of two shapes -- the items nested under the bundle line's `children`, or flat
// rows of table_sqt pointing back through parent_id -- so both are read here
// and turned into one list with each bundle's items directly after their
// bundle. A Get-many node returns the flat shape; the form returns the nested
// one.
//
// The tree is then rebuilt on the way out, because table_so expects a bundle to
// be one line with its items under `children`. A plain line gets no `children`
// key at all, so it does not render as an expandable row.
//
// A bundle line carries no item of its own, so its material and item category
// come out blank rather than as a null on an id-typed column.
// ==========================================================================
const flattenSqtLines = (lines) => {
  const rows = lines || [];

  const childrenOf = (line) => {
    const nested = Array.isArray(line.children) ? line.children : [];
    if (nested.length > 0) return nested;

    return rows.filter(
      (row) =>
        row.parent_id !== undefined &&
        row.parent_id !== null &&
        row.parent_id !== "" &&
        String(row.parent_id) === String(line.id),
    );
  };

  const claimed = new Set();

  rows.forEach((line) => {
    childrenOf(line).forEach((child) => {
      if (child && child.id !== undefined && child.id !== null) {
        claimed.add(String(child.id));
      }
    });
  });

  const flat = [];

  rows.forEach((line) => {
    if (claimed.has(String(line.id))) return;

    flat.push({ line: line, parentId: null });

    childrenOf(line).forEach((child) => {
      flat.push({ line: child, parentId: String(line.id) });
    });
  });

  return flat;
};

const mapLineItemToSOLine = (item, sqt, lineIndex) => {
  const materialId = referenceId(item.material_id);
  const orderUomId = referenceId(item.sqt_order_uom_id);

  const itemMaster = materialId
    ? itemById.get(String(materialId))
    : null;

  const packingDetails = Array.isArray(itemMaster?.table_packing_detail)
    ? itemMaster.table_packing_detail
    : [];

  const packingDetail = orderUomId
    ? packingDetails.find(
        (detail) =>
          String(referenceId(detail.uom_id)) === String(orderUomId)
      )
    : null;

  // An item with no packing row for this UOM is sold loose: one unit per pack,
  // so the line's quantity carries straight over. Falling back to 0 instead
  // would divide by zero on the packing quantity.
  const packingConversion = (packingDetail && packingDetail.quantity) || 1;

  const soLine = {
    item_name: referenceId(item.material_id) || "",
    item_id: item.material_name,
    so_desc: item.sqt_desc,
    so_quantity: parseFloat(item.quantity || 0),
    so_item_uom: referenceId(item.sqt_order_uom_id) || "",
    so_item_price: parseFloat(item.unit_price || 0),
    so_gross: parseFloat(item.sqt_gross || 0),
    more_desc: item.more_desc,
    line_remark_1: item.line_remark_1,
    line_remark_2: item.line_remark_2,
    line_remark_3: item.line_remark_3,
    so_discount: parseFloat(item.sqt_discount || 0),
    so_discount_uom: referenceId(item.sqt_discount_uom_id) || "",
    so_discount_amount: parseFloat(item.sqt_discount_amount || 0),
    so_tax_preference: referenceId(item.sqt_taxes_rate_id) || "",
    so_tax_percentage: item.sqt_tax_rate_percent,
    so_tax_amount: parseFloat(item.sqt_taxes_fee_amount || 0),
    so_tax_inclusive: item.sqt_tax_inclusive,
    so_brand: referenceId(item.sqt_brand_id) || "",
    so_packaging_style: referenceId(item.sqt_packaging_id) || "",
    so_amount: parseFloat(item.total_price || 0),
    plant_id: referenceId(sqt.sqt_plant),
    item_category_id: referenceId(item.item_category_id) || "",
    customer_id: referenceId(sqt.sqt_customer_id),
    payment_term_id: referenceId(sqt.sqt_payment_term),
    sales_person_id: referenceId(sqt.sales_person_id),
    billing_state_id: referenceId(sqt.billing_address_state),
    billing_country_id: referenceId(sqt.billing_address_country),
    shipping_state_id: referenceId(sqt.shipping_address_state),
    shipping_country_id: referenceId(sqt.shipping_address_country),
    sqt_id: String(sqt.id),
    // Pairs this order line back to the quotation row it came from, so a later
    // quotation edit cascades into exactly this line. SQT_CASCADE refuses any
    // line it cannot match, so an order converted before this existed is
    // deliberately left alone rather than guessed at.
    sqt_line_id: item.id ? String(item.id) : null,
    item_bundle_id: referenceId(item.item_bundle_id) || "",
    sqt_created_by_id: sqt.create_user || null,
    organization_id: referenceId(sqt.organization_id),
    line_status: "Draft",
    line_index: lineIndex,
    access_group: sqt.access_group,
    area_id: referenceId(sqt.area_id) || "",
    custom_fields: item.custom_fields || "",
    tariff_id: referenceId(item.tariff_id),
    further_description: item.further_description,
    so_shipping_date: item.expected_shipment_date,
    project_id: referenceId(item.project_id),
    // Stock as it stood when the quotation was priced, not as it stands now.
    unrestricted_qty: item.unrestricted_qty,
    base_unrestricted_qty: item.base_unrestricted_qty,
    min_quantity: item.min_quantity,
    max_quantity: item.max_quantity,
    from_historical: item.from_historical,
    min_price: item.min_price,
    max_price: item.max_price,
    packing_uom: referenceId(packingDetail?.packing_uom_id) || "",
    packing_conversion: parseFloat(packingConversion).toFixed(8),
    packing_qty: q8(
      parseFloat(item.quantity || 0) / packingConversion,
    ).toFixed(8),
  };

  return soLine;
};

const buildSoLines = (record, startIndex) => {
  const soRowBySqtLine = {};
  const topLevel = [];
  let lineIndex = startIndex;

  for (const entry of flattenSqtLines(record.table_sqt)) {
    const parentRow = entry.parentId ? soRowBySqtLine[entry.parentId] : null;
    let soLine;

    if (parentRow) {
      if (!Array.isArray(parentRow.children)) parentRow.children = [];

      // Children are numbered within their own bundle: line_index is a
      // top-level ordering everywhere else in the order.
      soLine = mapLineItemToSOLine(
        entry.line,
        record,
        parentRow.children.length + 1,
      );
      parentRow.children.push(soLine);
    } else {
      lineIndex++;
      soLine = mapLineItemToSOLine(entry.line, record, lineIndex);
      topLevel.push(soLine);
    }

    soRowBySqtLine[String(entry.line.id)] = soLine;
  }

  return { lines: topLevel, nextIndex: lineIndex };
};

const mapHeaderData = (
  data,
  soLineItems,
  lineItemLength,
  soPrefix,
  sqtIDs,
  sqtNos,
  plantID,
) => {
  const mappedData = {
    so_status: "Draft",
    so_no: soPrefix,
    sqt_no: sqtNos,
    sqt_id: sqtIDs,
    so_date: new Date().toISOString().replace("T", " "),
    so_sales_person: referenceId(data.sales_person_id),
    customer_name: referenceId(data.sqt_customer_id) || "",
    so_currency: data.currency_code,
    organization_id: referenceId(data.organization_id),
    plant_name: plantID || "",
    cust_billing_address: data.sqt_billing_address,
    cust_shipping_address: data.sqt_shipping_address,
    so_payment_term: referenceId(data.sqt_payment_term),
    so_delivery_method: referenceId(data.sqt_delivery_method_id),
    delivery_method_text: data.delivery_method_text || "",
    so_area_id: referenceId(data.sqt_area_id) || "",
    project_id: referenceId(data.project_id),

    di_shipping_method: data.di_shipping_method,
    di_driver_name: data.di_driver_name,
    di_ic_no: data.di_ic_no,
    di_driver_contact_no: data.di_driver_contact_no,
    di_shipping_company: data.di_shipping_company,
    di_transport_name: data.di_transport_name,
    di_vehicle_number: data.di_vehicle_number,
    di_est_delivery_date: data.di_est_delivery_date,
    di_est_arrival_date: data.di_est_arrival_date,
    di_pickup_date: data.di_pickup_date,
    di_validity_of_collection: data.di_validity_of_collection,
    di_tracking_number: data.di_tracking_number,
    di_freight_charges: data.di_freight_charges,

    cp_driver_name: data.cp_customer_pickup,
    cp_ic_no: data.cp_ic_no,
    cp_driver_contact_no: data.driver_contact_no,
    cp_vehicle_number: data.vehicle_number,
    cp_pickup_date: data.pickup_date,
    validity_of_collection: data.validity_of_collection,

    cs_courier_company: data.courier_company,
    cs_shipping_date: data.shipping_date,
    cs_tracking_number: data.cs_tracking_number,
    est_arrival_date: data.cs_est_arrival_date,
    cs_freight_charges: data.freight_charges,

    ct_driver_name: data.ct_driver_name,
    ct_ic_no: data.ct_ic_no,
    ct_driver_contact_no: data.ct_driver_contact_no,
    ct_delivery_cost: data.ct_delivery_cost,
    ct_vehicle_number: data.ct_vehicle_number,
    ct_est_delivery_date: data.ct_est_delivery_date,

    ss_shipping_company: data.ss_shipping_company,
    ss_shippping_date: data.ss_shipping_date,
    ss_freight_charges: data.ss_freight_charges,
    ss_shipping_method: data.ss_shipping_method,
    ss_est_arrival_date: data.est_arrival_date,
    ss_tracking_number: data.ss_tracking_number,

    tpt_vehicle_number: data.tpt_vehicle_number,
    tpt_transport_name: data.tpt_transport_name,
    tpt_ic_no: data.tpt_ic_no,
    tpt_driver_contact_no: data.tpt_driver_contact_no,

    table_so: soLineItems,
    so_total_gross: data.sqt_sub_total,
    so_total_discount: data.sqt_total_discount,
    so_total_tax: data.sqt_total_tax,
    so_total: data.sqt_totalsum,
    exchange_rate: data.exchange_rate,
    myr_total_amount: data.myr_total_amount,

    billing_address_line_1: data.billing_address_line_1,
    billing_address_line_2: data.billing_address_line_2,
    billing_address_line_3: data.billing_address_line_3,
    billing_address_line_4: data.billing_address_line_4,
    billing_address_city: data.billing_address_city,
    billing_postal_code: data.billing_postal_code,
    billing_address_state: referenceId(data.billing_address_state),
    billing_address_country: referenceId(data.billing_address_country),
    billing_address_name: data.billing_address_name,
    billing_address_phone: data.billing_address_phone,
    billing_attention: data.billing_attention,
    billing_address_fax: data.billing_address_fax,
    billing_address_code: data.billing_address_code,

    shipping_address_line_1: data.shipping_address_line_1,
    shipping_address_line_2: data.shipping_address_line_2,
    shipping_address_line_3: data.shipping_address_line_3,
    shipping_address_line_4: data.shipping_address_line_4,
    shipping_address_city: data.shipping_address_city,
    shipping_postal_code: data.shipping_postal_code,
    shipping_address_state: referenceId(data.shipping_address_state),
    shipping_address_country: referenceId(data.shipping_address_country),
    shipping_address_name: data.shipping_address_name,
    shipping_address_phone: data.shipping_address_phone,
    shipping_attention: data.shipping_attention,
    shipping_address_fax: data.shipping_address_fax,
    shipping_address_code: data.shipping_address_code,

    so_shipping_date: data.expected_shipment_date,
    so_tnc: data.sqt_tnc,
    so_payment_details: data.sqt_payment_details,
    so_delivery_term: data.sqt_deliveryterm,
    so_remarks: data.sqt_remarks,
    so_remarks2: data.sqt_remarks2,
    so_remarks3: data.sqt_remarks3,
    so_remarks4: data.sqt_remarks4,
    so_remarks5: data.sqt_remarks5,
    partially_delivered: `0 / ${lineItemLength}`,
    fully_delivered: `0 / ${lineItemLength}`,
    access_group: data.access_group,
    price_tag_id: referenceId(data.price_tag_id),

    so_type: "Credit",
    so_description: data.sqt_description,
    create_si: "No",
    si_status: "Not Created",
    production_status: "Not Created",
    so_created_by: data.create_user,
    acc_integration_type: data.acc_integration_type || "",
    page_status: "Add",
    created_source: createdSource,
    so_no_type: {{node:get_node_R8sMtBKG.data.data.id}},
  };

  return mappedData;
};

const soConvertType = {{workflowparams:so_type}};
const sqtData = {{node:search_node_bcw4wTuU.data.data}};
const createdSource = {{workflowparams:created_source}} || "Web";

const itemData = {{node:search_node_xewfGYma.data.data}} || [];

const itemById = new Map(
  itemData.map((item) => [String(item.id), item])
);

// "lines" mode: SQT_CASCADE asks for mapped order lines for specific quotation rows, so
// an item added to an already-converted quotation can be appended to its order. The
// SQT->SO line mapping lives here and ONLY here -- copying mapLineItemToSOLine into the
// cascade would fork ~70 columns across two workflows, and the next person to add a
// column would update one of them.
if (soConvertType === "lines") {
  const wanted = ({{workflowparams:line_ids}} || []).map(String);
  const picked = [];
  for (const record of sqtData) {
    // startIndex 0 is fine: SO_SAVE's code_node_BtxYhPym re-indexes line_index across
    // the whole order after the append.
    buildSoLines(record, 0).lines.forEach((line) => {
      // A bundle is taken whole, with its items still under `children`, because it is
      // ordered as a whole.
      if (wanted.indexOf(String(line.sqt_line_id)) >= 0) picked.push(line);
    });
  }
  return { soData: picked };
}

let soData = [];

if (soConvertType === "multiple") {
  for (const record of sqtData) {
    const built = buildSoLines(record, 0);

    // so_no stays blank: the Add Data node binds the serial rule straight off
    // Get SO Prefix Config, the way SO_Convert_GD does with delivery_no_type.
    const mappedData = mapHeaderData(
      record,
      built.lines,
      built.lines.length,
      "draft",
      [record.id],
      record.sqt_no,
      referenceId(record.sqt_plant),
    );

    soData.push(mappedData);
  }
} else {
  // Merging quotations from different customers into one order would put the
  // wrong billing and shipping header on half the lines.
  const customers = new Set(
    sqtData.map((record) => referenceId(record.sqt_customer_id)),
  );

  if (customers.size > 1) {
    throw new Error(
      "All selected quotations must be from the same customer to create a single sales order.",
    );
  }

  // Every quotation's lines flow into one order, numbered continuously across
  // the whole merged document rather than restarting per quotation.
  let soLineItems = [];
  let lineIndex = 0;

  for (const record of sqtData) {
    const built = buildSoLines(record, lineIndex);
    soLineItems = soLineItems.concat(built.lines);
    lineIndex = built.nextIndex;
  }

  const record = sqtData[0];
  const sqtNos = sqtData.map((item) => item.sqt_no).join(", ");
  const sqtIDs = sqtData.map((item) => item.id);
  const soPrefix = "";

  // Plant is left blank for the user to pick in the form, matching the single
  // path today.
  const mappedData = mapHeaderData(
    record,
    soLineItems,
    soLineItems.length,
    soPrefix,
    sqtIDs,
    sqtNos,
    "",
  );

  const sum = (field) =>
    sqtData.reduce(
      (total, sqt) => total + Number(sqt[field] || 0),
      0,
    );

  mappedData.so_total_gross = sum("sqt_sub_total");
  mappedData.so_total_discount = sum("sqt_total_discount");
  mappedData.so_total_tax = sum("sqt_total_tax");
  mappedData.so_total = sum("sqt_totalsum");
  mappedData.myr_total_amount = sum("myr_total_amount");

  soData.push(mappedData);
}

return {soData};
